public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String s = sc.next();
    boolean ok = true;
    if (s.charAt(0) < 'A' || s.charAt(0) > 'Z') {
        ok = false;
    } else {
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) >= 'A' && s.charAt(i) <= 'Z') {
                ok = false;
                break;
            }
        }
    }
    System.out.println(ok ? "YES" : "NO");
}
